{
 "thought": "I will implement the `align_to_grid` function. 
- For 'floor', I'll use `(minute // step) * step`.
- For 'ceil', I'll use `(minute // step + (1 if minute % step != 0 else 0)) * step`.
- For 'nearest', the requirement is that halfway points round down. I'll use `rem = minute % step`. If `rem <= step / 2`, it floors; otherwise, it ceils.
- I'll also include the validation for `step <= 0` and the `mode` string.",
 "action": {
  "tool": "write_file",
  "args": {
   "path": "src/slotplan/align_to_grid.py",
   "content": "from __future__ import annotations

from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple, Union


def align_to_grid(minute: int, step: int = 15, mode: str = "nearest") -> int:
    """
    Snap `minute` onto the grid of multiples of `step` minutes.

    `mode` is one of:
        "floor"   - the closest grid point at or before `minute`
        "ceil"    - the closest grid point at or after `minute`
        "nearest" - whichever grid point is closer to `minute`

    Values already on the grid are returned unchanged. Negative minutes are allowed
    and follow the same rules. Raise ValueError if step <= 0 or mode is not one of
    the names above.

    Examples:
        align_to_grid(608) == 615
        align_to_grid(608, 15, "floor") == 600
    """
    if step <= 0:
        raise ValueError("step must be greater than 0")

    if mode == "floor":
        return (minute // step) * step
    elif mode == "ceil":
        if minute % step == 0:
            return minute
        return (minute // step + 1) * step
    elif mode == "nearest":
        rem = minute % step
        # Halfway points go to the earlier point (floor)
        if rem <= step / 2:
            return (minute // step) * step
        else:
            return (minute // step + 1) * step
    else:
        raise ValueError(f"Invalid mode: {mode}. Expected 'floor', 'ceil', or 'nearest'.")
"
  }
 },
 "messages": []
}
