    try:
        h_str, m_str = text.split(':')
        if len(m_str) != 2:
            raise ValueError("Minutes must be two digits")
        hour = int(h_str)
        minute = int(m_str)
    except ValueError:
        raise ValueError("Invalid format. Expected HH:MM")

    if not (0 <= hour <= 24):
        raise ValueError("Hour must be between 0 and 24")
    if not (0 <= minute <= 59):
