def parse_hhmm(text: str) -> int:
    """
    Parse an 'HH:MM' clock time into minutes since midnight.
    Hours can be 0-23, or 24 if minutes are 00.
    """
    try:
        h_str, m_str = text.split(':')
        if len(m_str) != 2:
            raise ValueError("Minutes must be two digits")
        hour = int(h_str)
        minute = int(m_str)
    except ValueError:
        raise ValueError("Invalid format. Expected HH:MM")

    if not (0 <= hour <= 24):
        raise ValueError("Hour must be between 0 and 24")
    if not (0 <= minute <= 59):
        raise ValueError("Minute must be between 0 and 59")
    if hour == 24 and minute != 0:
        raise ValueError("24:00 is the only valid time with hour 24")

    if hour == 24 and minute == 0:
        return 0

    return hour * 60 + minute
"}}}
