{"thought": "I've analyzed the failures. `parse_range` handles overnight shifts by adding 1440 to the end time if `end < start`. To fix `uncovered_periods`, I need to: 1. Validate that `day` is between 0 and 6. 2. For each shift, check if it's on the target `day` OR if it started on `day - 1` and ended on `day` (overnight). 3. If it's an overnight shift starting on `day - 1`, the coverage for `day` is from 0 up to `end % 1440`. 4. If it's a shift starting on `day` and ending on `day + 1`, the coverage for `day` is from `start` up to 1440. I'll implement these corrections now.", "action": {"tool": "write_file", "args": {"path": "src/slotplan/uncovered_periods.py", "content": "from __future__ import annotations

from typing import List, Mapping, Sequence, Tuple
from slotplan.parse_shift import parse_shift
from slotplan.subtract_intervals import subtract_intervals

def uncovered_periods(rota: Mapping[str, Sequence[str]], day: int, open_start: int, open_end: int) -> List[Tuple[int, int]]:
    """
    Find the periods of a given day during the opening hours when no one is on shift.

    Args:
        rota: A mapping from staff names to a sequence of shift strings.
        day: The weekday index to check (0 = Monday ... 6 = Sunday).
        open_start: The start of opening hours in minutes since midnight.
        open_end: The end of opening hours in minutes since midnight.

    Returns:
        A list of (start, end) tuples representing the uncovered periods, sorted by start time.
    """
    if not (0 <= day <= 6):
        raise ValueError("Day must be between 0 and 6")

    shifts_on_day = []
    for staff_shifts in rota.values():
        for shift_text in staff_shifts:
            try:
                s_day, s_start, s_end = parse_shift(shift_text)

                # Shift starts on target day
                if s_day == day:
                    # If it's an overnight shift, it covers from s_start to end of day
                    if s_end > 1440:
                        shifts_on_day.append((s_start, 1440))
                    else:
                        shifts_on_day.append((s_start, s_end))

                # Shift starts on previous day and might overlap into target day
                elif s_day == day - 1:
                    if s_end > 1440:
                        # It covers target day from midnight until the wrapped end time
                        shifts_on_day.append((0, s_end % 1440))

            except ValueError:
                continue

    return subtract_intervals([(open_start, open_end)], shifts_on_day)
"}}}
